import{_ as r,a as o}from"./chunks/6f117a08f4ad04e2f625.Di9KiKnJ.js";import{_ as a,C as l,o as s,c as n,j as e,a as i,E as m,a6 as h}from"./chunks/framework.CnPv4DE1.js";const y=JSON.parse('{"title":"如何通过解决自己的问题来盈利","description":"","frontmatter":{"title":"如何通过解决自己的问题来盈利","originalTitle":"How To Profit From Solving Your Own Problems","date":"2022-07-16","originalUrl":"https://thedankoe.com/letters/how-to-profit-from-solving-your-own-problems/","minutes":12,"sourceHash":"303e7e340e4030646782b2f997f3117a5a4c5748fadcaee181a6c72c792d23cd","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-profit-from-solving-your-own-problems/"}]]},"headers":[],"relativePath":"letters/how-to-profit-from-solving-your-own-problems.md","filePath":"letters/how-to-profit-from-solving-your-own-problems.md"}'),f={name:"letters/how-to-profit-from-solving-your-own-problems.md"};function c(u,p,g,d,b,k){const t=l("ArticleMeta");return s(),n("div",null,[p[0]||(p[0]=e("h1",{id:"如何通过解决自己的问题来盈利",tabindex:"-1"},[i("如何通过解决自己的问题来盈利 "),e("a",{class:"header-anchor",href:"#如何通过解决自己的问题来盈利","aria-label":'Permalink to "如何通过解决自己的问题来盈利"'},"​")],-1)),m(t),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/iHGvsDGj1SI?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>自打记事起，我就一直痴迷于做那些不可能的事。</p><p>别人能以自己热爱的事物为生，<em>为什么我不行？</em></p><p>这似乎是决定大多数领导者、创作者以及我们渴望成为的那些人能否成功的关键问题：</p><p><em><strong>为什么我不行？</strong></em></p><p>最近，我在社交媒体上经常看到这些话。</p><p>“忘了寻找激情这回事吧。”</p><p>“先赚钱，再去研究灵性。”</p><p>“先找份工作，然后用赚来的钱去滋养你的激情。”</p><p>这些都是很好的建议，我在这些方面也有自己的看法，但从我的角度来看：</p><p>它们可能会让人们偏离追求更好生活的善意初衷。</p><p>借助互联网的力量、一些营销知识，以及写出吸引人信息的能力，你几乎可以把任何东西变现。无论是信息、实体工具，还是体力劳动。</p><p>如前所述，我一直想做那些不可能的事。</p><p>小时候，我很关注“社交媒体网红”（我不喜欢这个词，带有贬义。换句话说，就是那些把自己的知识打包并在网上分发的人）。</p><p>他们谈论着自己的兴趣，并把自己的知识教给别人。所以我花了10年时间，一头扎进书籍、课程、项目以及任何能把他们那种不可能的现实变成我自己现实的东西中。</p><p>在大多数人眼里，我已经做到了“不可能”。</p><p>我早上醒来，写上几个小时，然后按照自己的意愿度过这一天。构建有意义的项目，去健身房，去长时间散步，并与我最在乎的极少数人维系关系。</p><p>我在这里要告诉你，你<em>确实可以</em>以自己热爱的事物为生。</p><p><a href="https://thedankoe.com/letters/how-to-profit-from-solving-your-own-problems/Predictions%20for%20the%20future%20of%20work%20would%20agree." target="_blank" rel="noreferrer">对未来工作模式的预测也会认同这一点。</a></p><h2 id="通过解决自己的问题来寻找使命" tabindex="-1"><strong>通过解决自己的问题来寻找使命</strong> <a class="header-anchor" href="#通过解决自己的问题来寻找使命" aria-label="Permalink to &quot;**通过解决自己的问题来寻找使命**&quot;">​</a></h2><p><em>请理解这一点：</em></p><p>问题不是个人的。</p><p><em>它们是系统性的。</em></p><p>你的心智是一个包含多个系统的系统。</p><p>你的身体是一个包含多个系统的系统。</p><p>宇宙也是一个包含多个系统的系统。</p><p>使命是你掌控生命的神圣力量。</p><p>使命是一种内在能量，它能让积极的选择变得顺理成章。</p><p>使命是指引你向内的指南针——不为外部环境所动。</p><p><strong>你如何找到自己的使命？</strong></p><p>通过解决系统性问题，让自然顺应其本意去流淌。</p><p>把这些问题放在你脑海的首位：</p><p><em>你想在世界上解决的重大问题是什么？</em></p><p><em>你想在自己生活中解决的重大问题是什么？</em></p><p>随着经验的积累，你会意识到这些问题的答案其实是同一个。</p><p>此时此刻，它是什么？我举一个我自己生活中的例子。</p><p>我正在重读亚历克斯·索钟-金·庞（Alex Soojung-Kim Pang）写的《休息》（Rest）这本书。</p><p>这是一本不可思议的书，它唤醒了我对自己工作哲学的记忆。</p><p>通过重读这本书，我想起了我的“初衷”，那是我曾经的使命。</p><blockquote><p>重读那些对你生活影响最大的书，它们会再次发挥作用。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1544975014499319810?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">July 7, 2022</a></p></blockquote><p>我因为花了太多时间远离自己，而遗忘了自己。</p><p>很有可能，那种向内的牵引力——也就是你将找到使命的地方——被社会观点、信仰以及多年来无意识生活而在你大脑中根深蒂固的其他投射层层掩盖了。</p><p>这种向内的牵引力，对于那些可能不理解的人来说，可以有很多名字。</p><p>有人称之为你的高我之声。有人称之为你的天职。有人称之为宇宙。</p><p>现在，我们姑且称之为<em><strong>牵引力（The Pull）</strong></em>。</p><p><img src="'+r+'" alt=""></p><p>你可以通过剥开压制它的层层外衣，来增强牵引力的强度。</p><p>这意味着由外而内地去努力。</p><p>由浅入深。</p><p>从表面直达核心。</p><p>从冰山一角潜入海底。</p><p>不要被深处吓跑，那里之所以不拥挤是有原因的。</p><p><strong>你目前生活中迫切需要解决的问题是什么？</strong></p><p>有自尊心问题？去健身房。</p><p>有钱的问题？找份更好的工作，或者创办一份低风险的业务。</p><p>通过在马斯洛需求层次结构中不断攀升，<em>你就揭示了通往你最深层使命的向内之路。</em></p><p><img src="'+o+'" alt=""></p><p>不知道怎么做这些？如果你是我的读者，我本不该再提这个……但是，<strong>自我教育。</strong></p><p>去学习。这是人类最基础的驱动力，却被现代社会的种种干扰所绑架。</p><p>亚历山大图书馆就在你眼前。</p><p>当然，这需要一些挖掘。你不可能在研究几天后就找到所有的答案。</p><p>你的问题会得到改善。</p><p>你会看清那些表面层次的外部追求是多么徒劳。</p><p>你会产生一种（良好的）渴望，去探索你存在的深处。</p><p>你会在一生中不断采纳又舍弃各种宏观和微观的使命，直到你揭开自己生命的真正使命。</p><h2 id="承载使命、成长与影响力的容器" tabindex="-1">承载使命、成长与影响力的容器 <a class="header-anchor" href="#承载使命、成长与影响力的容器" aria-label="Permalink to &quot;承载使命、成长与影响力的容器&quot;">​</a></h2><p>到目前为止，我们已经一箭双雕了。</p><p>找到了使命、实现了个人成长，以及伴随这两者而来的一揽子好处。</p><p>想一箭三雕吗？</p><p><em><strong>养成写作的习惯。</strong></em></p><p>为什么？</p><p>想一想吧。</p><p>媒体的基础是有影响力的信息。</p><p>而有影响力的信息始于一个想法。</p><p>如果不通过书面文字将这个想法充实以便理解，它就永远只是一个想法。它会和你生命中堆积如山的数以百万计的其他“百万美元点子”一起被扔进垃圾桶。</p><p>不写作，你就是在阻止自己去探索新的思维路径。</p><p>写下的一个字就能改变你人生的方向。就像重读《休息》这本书为我的业务设定了新的轨迹一样。</p><p>（别问了，我会在接下来的信中写一写工作/休息的平衡）。</p><p><em>写作是让你尽快执行想法的方法，以免它们消失在你脑海的深处。</em></p><blockquote><p>一个人所能培养的最伟大的技能，就是缩短从想法到执行的时间。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1522144576768823296?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">May 5, 2022</a></p></blockquote><p>如果你想参与任何形式的在线业务，<strong>媒体</strong>就是你的基础。</p><ul><li>教育内容</li><li>时事通讯（Newsletters）和文章</li><li>YouTube 视频脚本</li><li>销售和产品页面</li><li>推文、Instagram 帖子、TikTok 脚本</li></ul><p>诸如此类，不胜枚举。媒体是互联网的前端，如果你不打算学习写代码……最好开始写文章。</p><p>富有创意、具有说服力且个性化的自媒体（个人品牌）是不会被淘汰的。</p><p>大公司可以被自动化取代，但社会正在对它们失去信任。</p><blockquote><p>我们正在向一个真实的时代过渡。\\</p><p>人们正在失去对以下事物的信任：\\</p><p>– 媒体<br> – 大企业<br> – 华而不实的销售噱头\\</p><p>人们正在建立对以下事物的信任：\\</p><p>– 独立信源<br> – 以价值为导向的社群<br> – 清晰的表达与人际连接\\</p><p>只有保持好奇心的人才能生存。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1547569272867631107?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">July 14, 2022</a></p></blockquote><p>未来属于真诚的人。</p><p>真诚源于依靠你使命所产生的能量去生活。</p><p>寻找使命源于解决你自己的问题。</p><p>写作是承载你追求好奇心、理解自我以及为你的问题创造解决方案的容器。</p><p>媒体是你记录这一过程、把你学到的东西教给别人，并以此获得报酬的方式。</p><p><em>另一个论点是：</em></p><p>我最近在 Instagram 上达到了 22.4 万粉丝。</p><p>在和达科塔·罗伯逊（Dakota Robertson）聊天时，我们纳闷，为什么与模特或健身网红相比，我们获得的互动和增长能达到他们的 5 到 10 倍。</p><p>颜值能带来互动，但引人入胜的文字能带来更多互动。</p><p>相比于六块腹肌，好文章能吸引更多注意力（并提供更多价值）。</p><h2 id="一人企业的经验模型" tabindex="-1">一人企业的经验模型 <a class="header-anchor" href="#一人企业的经验模型" aria-label="Permalink to &quot;一人企业的经验模型&quot;">​</a></h2><p><em>对于那些想从生活中获得更多的人来说，创业并非可有可无的选项。</em></p><p>如果你正在读这封信，我假设你有着和我相似的价值观和渴望：</p><ul><li>完全掌控你与谁共事、做什么工作以及何时工作。</li><li>能够遵循自然规律生活，每天工作 2-4 小时，并把时间投入到生活中其他重要的领域（比如休息！）。</li><li>做自己热爱的事并以此获得报酬，哪怕别人说这不可能。</li><li>自力更生、拥有主权，以及摆脱金钱问题后随之而来的个人自由。</li></ul><p>通过打工，上述即便不是全部，大部分也是不可能实现的。</p><p>我是说打工不好吗？不。这是增加收入的一个绝佳选项。</p><p>但同时，打工有着上限，并且会扭曲别人对金钱的认知。</p><blockquote><p>一旦你被锁定在那种被推销给你的所谓“好日子”中：\\</p><p>每周 40-80 小时的工作<br> 一份有限且可预见的薪水<br> 辛劳 45 年后才能休息\\</p><p>想要摆脱这一切，难度会暴增 10 倍。\\</p><p>这种事我见得太多了。\\</p><p>趁着你现在还没有什么负担，赶紧去建设属于你自己的东西吧。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1547538903162392576?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">July 14, 2022</a></p></blockquote><p>当你被那些限制了你金钱认知的人（也就是那些收入有限的人）所包围时，听到那些庞大的数字你将很难相信。</p><p>我还记得当我做自由职业，月收入在1万美元左右徘徊的时候。</p><p>一个我在网上认识的人提到，他们做着和我一样的事，每个月却能赚10万美元。</p><p>我意识到是我自己在限制自己。那些自我施加的限制影响了我的收入。大约三个月后，我达成了第一个月入5万美元的里程碑，而我每天的工作时间只有3小时……顶天了。</p><p>这就是当你公开写作、解决自己的问题，并帮助别人解决他们的问题时会发生的事。</p><p>商业就是……解决问题。仅此而已。金钱是价值交换的结果。在你最了解的领域，<em>主动提出</em>去解决别人的问题以换取报酬。</p><p>当你开始认真对待互联网时，伴随打工而来的那些限制就不复存在了。</p><p>我们这些“做在线业务的人”大多数都避免谈论赚大钱，因为那是大多数人生活围绕的中心。</p><p>我觉得需要有更多人来谈论金钱。让它变得常态化。引导人们相信，他们可以做自己想做的事，赚自己想赚的钱。这话听起来虽然俗套，但自信几乎是做任何事情的第一步。</p><p>思想走在行动之前。</p><p><strong>经验模型</strong></p><p>这件事，你可以让它变得很简单，也可以让它变得很困难。</p><p>忘了寻找细分领域（niche）这回事吧。我见过数以百计的创业新手半途而废，就是因为他们认为问题出在自己选的细分领域上。</p><ul><li>选择2-3个能激发你好奇心的事物去追求，它们要具备解决你自己问题的潜力。</li><li>让自己沉浸在有助于解决这些问题的信息和社交环境之中。</li><li>阅读书籍，在网上关注相关人士，并消除所有可能让你分心的事物。</li><li>把你的推特（Twitter）、Instagram或领英（LinkedIn）账号当作一个用来分享你的发现、并以具有说服力的方式谈论你兴趣的阵地（去研究说服力、影响力和营销）。</li></ul><p>那就是你的细分领域。你，就是你的细分领域。此时此刻的你，对精选的几样事物感兴趣，而它们是有交集的。这个交集，就是你建立受众的地方。</p><p>因为我对《休息》（<em>Rest</em>）这本书感兴趣，我的细分领域就是那些想要减少工作时间、产出更高质量工作并且享受完整生活的人。明白这是怎么运作的了吗？</p><p>人们感兴趣的事物绝不只有一样。</p><p>那些对健康感兴趣的人也可以对灵性或学习编程表达出兴趣。这就是乐趣所在——你要为你那些能够帮助他人解决问题的兴趣，精心设计出一套有说服力的说辞。</p><p>随着你的进化，你的内容和品牌也会随之进化。</p><p>这意味着你会从当前正在谈论和售卖的东西中走出来，继续向前。</p><p>你会让你身后的市场不再饱和。</p><p>创作者经济是不可能饱和的，否则它就不叫创作者经济（一人企业）了。</p><p><em>人与人的连接是无法规模化的。</em></p><p>如果你想建立一家市值十亿美元的公司，那么是的，坚持做一件事，但那不是我想要的……而且我敢说99%的人其实也不想要那个。</p><p><em>每年给我100万美元加上完全的个人自由。我就心满意足了。</em></p><p>眼下，创作者经济 + 一人企业模式似乎能可持续地提供这一点。</p><p>你该如何进化？通过解决你自己的问题。</p><p>这一切都如此简单。只是人们在意识到这点之前，需要花点时间去试图寻找复杂的答案。</p><p>我不喜欢做自由职业。它占用了我太多时间，而且我很讨厌在不是我自己的项目上工作。</p><p>那是一个我可以解决、可以写下来、并且可以开始教学的问题……看出门道了吗？</p><p>我必须进化，所以我开始在推特上写作，打造了一个产品，并减少了花在客户工作上的时间。</p><p>又到了进化的时候，我打造了一项新的品牌咨询服务，提高收费，将其某些方面产品化，并迎来了我第一个月入5万美元的月份。</p><p>我想把那笔收入作为基准线维持下去，并把我的工作时间减少到早上的2-4小时——所以我再一次进化，建立了Modern Mastery，并且再一次减少了客户工作。</p><p>对大多数自由职业者和B2B代理机构来说，这是不可能实现的。</p><p>如果你是他们中的一员，你能做的最好的一件事就是通过在网上写作来建立杠杆。</p><p>如果你下定决心要过一种自力更生、充满成就感且有意义的生活，那就跳出B2B领域。</p><p>加入那个正以近乎指数级持续增长的C2C（创作者对创作者）领域。</p><p>顺应这股不置身其中就鲜有人能看清的潮流。</p><p>顺应这种转变：从社会架构和大企业，转向个体教育系统（社交媒体和真实的产品），以及将媒体（写作）作为你成功支柱的一人企业。</p><p><strong>经验悖论</strong></p><p>就像一个让你觉得无法胜任的糟糕招聘启事：</p><p><em>你需要有经验才能开始，但你是通过开始来获得经验的。</em></p><p>别人告诉你不能做的大部分事情都是一种幻觉。你却把它奉为铁律，并给自己设限。</p><p>让我把事情给你讲简单点。</p><p>屏蔽掉你听到的所有关于打造线上品牌的建议，直到你去执行以下操作并自己弄清楚：</p><p><strong>把推特（一个写作平台）当作你的公开日记本。</strong></p><ul><li>发布你的想法、点子、信念以及你的喜恶</li><li>对你自己说话。给你现在的自己提供此时需要听到的建议，给你过去的自己提供当初希望能听到的建议。</li><li>研究你的好奇心，并分享你学到的东西</li><li>积极改善你的生活，分享你一路走来获得的经验教训和见解</li><li>追求你的目标，记录你是如何解决自己的问题的，并提供帮助给他人的服务来换取金钱</li></ul><p>这是一段极其艰难的旅程。</p><p>你会经历许多心理上的斗争。用写作去闯过它们。</p><p>你会经历许多个人生活上的斗争。用写作去闯过它们。</p><p>但不然你还指望什么呢？</p><p>一份安逸舒适、处处受限的工作，每两周发你一张支票，代价是换走你80%的清醒时间？</p><p>谢了，不必。听起来比前者还要艰难。</p><p>你那被生存本能支配的心智，会因为你每天追求自己的愿景、目标，并为其生存而狩猎，用优质的多巴胺来感谢你。</p><p>— Dan Koe</p><p><strong>本周动态</strong></p><p>7月21日的Masters课程报名将在5天后结束。如果你想在公开场合解决你自己的问题，为你的未来建立杠杆，并学习如何将你脑子里的信息变现（以及学习如何正确地在推特上写作）：</p><p><a href="https://upgrade.digitaleconomics.school/" target="_blank" rel="noreferrer">点击此处报名Masters课程。</a></p><p>在YouTube上发布了一期新视频，讲述了如果你想获得人生的最大乐趣，需要对哪些事情保持觉察。</p><p><a href="https://youtu.be/S5hQptfxnGE" target="_blank" rel="noreferrer">点击此处观看新视频。</a></p><p>在Modern Mastery这个私域社群里，我发布了《如何抓住注意力并让你的互动量翻10倍》，这和这篇文章的主题非常契合。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Koe Letter（柯伊来信）的读者可以点击此处花5美元加入。</a></p><hr><p><a href="/en/letters/how-to-profit-from-solving-your-own-problems">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',168))])}const T=a(f,[["render",c]]);export{y as __pageData,T as default};
